INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cubenen Gardens: Befriend', 'Cubenen Gardens: Befriend is a story-driven indie RPG where you play as Michael, a nerdy kangaroo inventor from the Tech District. They have a lifelong goal of making monsters less of a threat to society. And their research takes them to the abandoned offices of the Mall District to test a theory regarding how monsters relate to the memories of the deceased. Things go well, but then they get caught up in a corporate nightmare. Slowly breaking them down and leaving them desperately searching for a way to escape.' FROM games WHERE igdb_id = 316148 ON CONFLICT (game_id, language_code) DO NOTHING;
