INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farming Simulator VR', 'In a relaxing hands-on experience, Farming Simulator VR brings you closer to the soil: Cultivate your fields with yielding crops like corn, wheat & soy. Operate authentic agricultural machinery by renowned manufacturers, directly in the cabin of powerful tractors. Grab repair tools to maintain your vehicles and their parts in the workshop. Tend to vegetables in the greenhouse, and don’t forget to keep your machines sparkling-clean with the pleasure of power-washing!' FROM games WHERE igdb_id = 329875 ON CONFLICT (game_id, language_code) DO NOTHING;
