INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inventorix', 'Inventorix, your trusty high-tech space asset inventory device, holds the key to extracting value from the vast resources scattered across the cosmos. But this marvel of technology comes at a price—quite literally. You secured it through a questionable loan scheme, and now you''re on the hook to pay off your ever-increasing debt before the space loan sharks come knocking.' FROM games WHERE igdb_id = 258604 ON CONFLICT (game_id, language_code) DO NOTHING;
