INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Subterror', 'At the bottom of the ocean floor lie The Biospheres. These weather-controlled domes once supported vast arrays of lifeforms, but have since been abandoned. Explore arid deserts, dark forests, and frozen tundras. But don''t stay too late, as you are not alone out in the great abyss.' FROM games WHERE igdb_id = 291576 ON CONFLICT (game_id, language_code) DO NOTHING;
