INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brews & Bastards', 'Brews & Bastards is a chaotic co-op dungeon crawler for 1-4 players, overflowing with action-packed combat, magical brews and outlandish tavern games. Select from a group of distinct heroes and blast your way through hordes of drunken demons in search of the stolen Brew Stone.' FROM games WHERE igdb_id = 265392 ON CONFLICT (game_id, language_code) DO NOTHING;
