INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '77Survival Part I', '77Survival is a survival game set in a post-apocalyptic world. Players will control four characters who accidentally find themselves stranded on the rooftop of a 77-story building. Their mission is to survive as long as possible or venture down to the first floor to uncover the mysterious events happening in the building. Each character has unique abilities, allowing them to solve puzzles and complete missions. If all four characters die, the game is over.' FROM games WHERE igdb_id = 314064 ON CONFLICT (game_id, language_code) DO NOTHING;
