INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foss Park', 'Foss Park is a psychological horror VN that takes you deep into the fractured mind of a nameless patient in an unsettling mental hospital. You awaken with no memory of how you arrived, haunted by fleeting images of a life destroyed—a house fire, a lost family, and echoes of a forgotten tragedy.' FROM games WHERE igdb_id = 330581 ON CONFLICT (game_id, language_code) DO NOTHING;
