INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop DS', 'Pop DS is a match 3 game with a twist, you POP (don''t swap) gems to remove them. As you progress you will learn new moves and encounter lots of on grid interactive objects. Enjoy playing the game casually, or aim for a challenge worthy of a gamer and go for 100% completion!' FROM games WHERE igdb_id = 326190 ON CONFLICT (game_id, language_code) DO NOTHING;
