INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shoomer Booter', 'An unexpected find at an antique shop, a soy boy stumbles upon an ancient beard ointment. Each night, he slips into a dream where he embodies a Sumerian warrior, tracing his lineage to Gibil. In this fantastical realm, he courageously confronts demons that lurk within the mystical attics of Irkalla.' FROM games WHERE igdb_id = 287717 ON CONFLICT (game_id, language_code) DO NOTHING;
