INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Randal''s Tuesday', 'Everything begins on a Wednesday, early in the morning. Our three protagonists are testifying in front of the Student Council leaded by no other than the Dean himself. They have been accused of committing a horrendous act (players don’t know about it just yet) and this is the only chance they have to try and clean their names.' FROM games WHERE igdb_id = 248200 ON CONFLICT (game_id, language_code) DO NOTHING;
