INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RPG Developer Bakin', 'RPG Developer Bakin (the correct pronunciation is "BAH-keen") is a game development tool that allows anyone to enjoy creating RPGs with intuitive operation and advanced features without programming. It includes a map editor, camera tool, and other tools to help you create your game, as well as graphics and sound assets that you can make your game from the day you purchase it. Games created can be distributed royalty-free with or without compensation. Now, bring “your vision of the world” to life with Bakin!' FROM games WHERE igdb_id = 228016 ON CONFLICT (game_id, language_code) DO NOTHING;
