INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Remember Valentine', 'Celebrate the holiday with Remember Valentine, a festive card-matching memory game perfect for all ages! Flip cards to reveal delightful Valentine-themed icons like hearts, candies, and Cupid himself, while testing your memory across increasing levels of fun and challenge. With cheerful visuals, cozy music, and endless holiday spirit, it’s the perfect way to make your gaming season merry and bright!' FROM games WHERE igdb_id = 330967 ON CONFLICT (game_id, language_code) DO NOTHING;
