INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farm Wars', 'Set a price for your farm and protect it. Your shapeshifter farmer will help you harvest your farm and destroy your rival’s farm. Farm Wars is a top-down PvP farm game against time. Create a strategy for your opponent and purchase their farm. Pay attention to the mines while making your attack!' FROM games WHERE igdb_id = 219291 ON CONFLICT (game_id, language_code) DO NOTHING;
