INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lord O'' Pirates', 'Lord O'' Pirates is a difficult yet casual bullet heaven roguelite which puts you at the helm of your very own pirate ship. Engage in naval combat against hordes of military ships, sea monsters, supernatural entities, and [REDACTED]. Loot gold and use it to unlock new ships, captains, and upgrades!' FROM games WHERE igdb_id = 258528 ON CONFLICT (game_id, language_code) DO NOTHING;
