INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endeavor', 'A sci-fi real-time strategy game with free form base building and all of the typical features found in classic RTS offerings. Construct a base, collect resources, build defenses, train an army, research technology and destroy the enemy. Manage your army with unit formations, patrol routes and attack groups, reveal the enemy through fog of war, monitor the battlefield with radar, one-click support abilities, unique unit attacks, hero units, etc. Combat balanced with a rock-paper-scissor approach to unit balance.' FROM games WHERE igdb_id = 301527 ON CONFLICT (game_id, language_code) DO NOTHING;
